import { expect, it } from 'vitest'
import { waitForFrame } from '@orkestrel/test/browser'

it('measures keyword permutations, synchronous readback, and the native shift', async () => {
	const anchor = document.createElement('button')
	const panel = document.createElement('div')
	anchor.style.cssText = 'position:fixed;left:180px;top:0;width:40px;height:30px;anchor-name:--probe'
	panel.style.cssText = 'position:fixed;position-anchor:--probe;position-area:block-start;width:120px;height:80px;margin:0;inset:auto'
	document.body.append(anchor, panel)
	const readings: unknown[] = []
	try {
		for (const tactic of ['none', 'flip-block', 'flip-inline', 'flip-start', 'flip-start flip-block', 'flip-start flip-inline', 'flip-block flip-inline', 'flip-block flip-inline flip-start']) {
			panel.style.setProperty('position-try-fallbacks', tactic)
			const synchronous = { area: getComputedStyle(panel).getPropertyValue('position-area'), box: panel.getBoundingClientRect().toJSON() }
			await waitForFrame()
			readings.push({ tactic, synchronous, framed: { area: getComputedStyle(panel).getPropertyValue('position-area'), box: panel.getBoundingClientRect().toJSON() } })
		}
		anchor.style.top = '200px'
		anchor.style.left = '0px'
		panel.style.setProperty('position-try-fallbacks', 'none')
		const shifted = panel.getBoundingClientRect().toJSON()
		panel.style.setProperty('justify-self', 'unsafe center')
		const unsafe = panel.getBoundingClientRect().toJSON()
		console.log(JSON.stringify({ readings, shifted, unsafe }))
		expect(shifted.x).toBe(0)
		expect(unsafe.x).toBe(-40)
	} finally {
		anchor.remove()
		panel.remove()
	}
})

