import { it, expect } from 'vitest'
import { waitForFrame } from '@orkestrel/test/browser'
import { requireValue } from '@orkestrel/test'
import { createPlacementFixture, readPlacementGeometry } from '../../tests/setupBrowser.js'
import { Placement } from '../../src/browser/Placement.js'
import 'bootstrap/dist/css/bootstrap.css'

it('measures initial and updated Popper geometry after replacing Bootstrap modifiers', async () => {
	const fixture = await createPlacementFixture({ name: 'popover-disabled-flip', plugin: 'Popover', placement: 'right', edge: 'right', attributes: { 'data-bs-popper-config': '{"modifiers":[{"name":"flip","enabled":false}]}' } })
	const placement = new Placement(fixture.options)
	try {
		await waitForFrame()
		const initial = readPlacementGeometry(fixture.expected, fixture.expectedArrow)
		const native = readPlacementGeometry(fixture.panel, fixture.arrow)
		const css = fixture.expected.style.cssText
		const arrow = fixture.expectedArrow?.style.cssText
		await fixture.oracle.call(requireValue(fixture.oracle.document.getElementById('popover')), 'update')
		await waitForFrame()
		const updated = readPlacementGeometry(fixture.expected, fixture.expectedArrow)
		console.log(JSON.stringify({ initial, native, updated, css, arrow }))
		expect(Math.abs(initial.box.y - updated.box.y)).toBeGreaterThan(1)
		expect(Math.abs(native.box.y - updated.box.y)).toBeLessThanOrEqual(1)
	} finally {
		placement.destroy()
		fixture.destroy()
	}
})

